"""Exploration: layered identity-triple DP tiling."""
import sys; sys.path.insert(0,'scratch/t74')
from _probe import load
import struct

def cand(raw, lo, hi, width=12, marker=False, align=None):
    """Yield (end_pos, ordinal, uid1, uid2) for every position where a 12B identity
    triple ends at end_pos and satisfies uid1==uid2, uid>0, ordinal>=0."""
    out=[]
    for p in range(lo, hi-width+1):
        if align is not None and (p % 4) != align:
            continue
        o,u1,u2 = struct.unpack_from('<III', raw, p)
        if u1 != u2 or u1 == 0:
            continue
        if marker and raw[p+12] != 0:
            continue
        out.append((p+width, o, u1))
    return out

def tile(raw, header, footer, n, width=12, marker=False, align=None,
         strict_uid=True, name_first=False):
    end = len(raw)-footer
    cs = cand(raw, header, end, width, marker, align)
    by_ord = {}
    for e,o,u in cs:
        by_ord.setdefault(o, []).append((e,u))
    for k in by_ord: by_ord[k].sort()
    if not all(k in by_ord for k in range(n)):
        return None, {k: len(by_ord.get(k,[])) for k in range(n) if k not in by_ord}
    # layered DP: state (end_pos, last_uid) -> count, but we just need reachability+count
    # layer 0: row0 start == header
    start = header
    cur = {start: [0]}  # end_pos -> list of last uid (keep minimal?)
    # simpler: DP over dp[i] = dict end_pos -> list of lastuid
    dp = [dict() for _ in range(n+1)]
    dp[0][header] = [0]
    for i in range(n):
        nxt = {}
        for pos, uids in dp[i].items():
            for e,u in by_ord.get(i, []):
                if e - width < pos:  # row is [pos, e)
                    continue
                if e - width == pos or e-width > pos:
                    if e-width != pos: continue
                good = [lu for lu in uids if (not strict_uid) or u > lu]
                if not good: continue
                nxt.setdefault(e, []).extend([u]) if u not in nxt.get(e,[]) else None
        dp[i+1] = nxt
        if not nxt: return 0, f"layer {i} empty"
    return (1 if end in dp[n] else 0), {i: len(dp[i]) for i in range(n+1)}

if __name__ == '__main__':
    tests = [('client',7,208),('server',7,208),('client',18,1567),('server',18,1567),
             ('client',27,334),('server',27,334),('client',8,126),('server',8,126)]
    for arch,tid,n in tests:
        raw = load(arch,tid)
        for width,marker in ((12,False),(13,True)):
            for align in (None,0,1,2,3):
                ok, info = tile(raw,14,8,n,width,marker,align)
                print(arch,tid,'w',width,'mk',marker,'align',align,'->',ok, str(info)[:90])
        print()

"""Exploration: layered identity-triple DP tiling (corrected)."""
import sys; sys.path.insert(0,'scratch/t74')
from _probe import load
import struct, collections

def build_cands(raw, lo, hi, W, align=None, require_marker=False, require_uid_eq=True):
    """(p, ordinal, uid) where a W-byte identity trailer starts at p."""
    out = collections.defaultdict(list)
    p = lo
    n = 0
    for p in range(lo, hi - W + 1):
        if align is not None and (p - lo) % 4 != align:
            continue
        o, u1, u2 = struct.unpack_from('<III', raw, p)
        if require_uid_eq and u1 != u2:
            continue
        if u1 == 0:
            continue
        if require_marker and raw[p+W-1] != 0:
            continue
        out[o].append((p, u1))
        n += 1
    return out, n

def count_tilings(raw, header, footer, n, W, align=None, require_marker=False,
                  strict_uid=True, min_row=1, max_states=200000):
    end = len(raw) - footer
    cands, ncand = build_cands(raw, header, end, W, align, require_marker)
    layers = [cands.get(i, []) for i in range(n)]
    layers = [sorted(l) for l in layers]
    missing = [i for i, l in enumerate(layers) if not l]
    if missing:
        return 0, {'missing_layers': missing[:10], 'n_cand': ncand}
    # dp[i]: pos -> count, plus last uid for constraint => keep dict pos -> dict(uid->count)
    dp = [dict() for _ in range(n+1)]
    dp[0][header] = {0: 1}
    for i in range(n):
        nxt = {}
        for pos, uids in dp[i].items():
            for pk, uid in layers[i]:
                if pk < pos + min_row - W and pk < pos:
                    continue
                if pk < pos:
                    continue
                e = pk + W
                if e > end:
                    continue
                for lu, c in uids.items():
                    if strict_uid and uid <= lu:
                        continue
                    d = nxt.setdefault(e, {})
                    d[uid] = d.get(uid, 0) + c
        # prune
        tot = sum(sum(v.values()) for v in nxt.values())
        if tot == 0:
            return 0, {'broke_at': i, 'n_cand': ncand}
        # collapse: keep only minimal uid per pos (dominant state) if counts explode
        if len(nxt) > max_states:
            return None, {'overflow_at': i, 'states': len(nxt)}
        dp[i+1] = nxt
    final = dp[n].get(end, {})
    paths = sum(final.values())
    return paths, {'n_cand': ncand, 'states_last': len(dp[n])}

if __name__ == '__main__':
    tests = [('client',7,208),('server',7,208),('client',18,1567),('server',18,1567),
             ('client',27,334),('server',27,334),('client',8,126),('server',8,126),
             ('client',56,6),('server',56,6),('client',47,2488),('server',47,2488)]
    for arch,tid,n in tests:
        raw = load(arch,tid)
        for W,mk in ((13,True),(12,False)):
            for align in (0,1,2,3,None):
                for foot in (8,):
                    p,info = count_tilings(raw,14,foot,n,W,align,mk)
                    if p:
                        print(arch,tid,'W',W,'mk',mk,'align',align,'foot',foot,'-> paths',p,info)
        print()

