"""Vectorized identity-triple DP (t57-style) + path reconstruction."""
import sys; sys.path.insert(0,'scratch/t74')
from _probe import load
import struct, collections

def cands(raw, lo, hi, W=13, marker=True):
    """Return layers: dict ordinal -> sorted list of (start,end)."""
    out = collections.defaultdict(list)
    # fast scan with struct
    for p in range(lo, hi - W + 1):
        o, u1, u2 = struct.unpack_from('<III', raw, p)
        if u1 != u2 or u1 == 0:
            continue
        if marker and raw[p+W-1] != 0:
            continue
        out[o].append(p)
    return out

def dp(lo, hi, n, layers, W=13):
    """Return (n_paths, chosen path) with strict increasing uid and exact tiling."""
    # forward: reach[i] = dict pos -> dict(uid -> pathcount)
    reach = [dict() for _ in range(n+1)]
    reach[0][lo] = {0: 1}
    for i in range(n):
        nxt = {}
        lay = layers.get(i, [])
        for pos, uids in reach[i].items():
            for p0 in lay:
                if p0 < pos:
                    continue
                e = p0 + W
                if e > hi:
                    break
                for u, c in uids.items():
                    o, u1, _ = struct.unpack_from('<III', raw_, p0)
                    if u1 <= u:
                        continue
                    d = nxt.setdefault(e, {})
                    d[u1] = d.get(u1, 0) + c
        reach[i+1] = nxt
        if not nxt:
            return 0, None, i
    return sum(reach[n].get(hi, {}).values()), reach, n

def solve(raw, n, header=14, footer=8, W=13, marker=True):
    global raw_
    raw_ = raw
    hi = len(raw) - footer
    layers = cands(raw, header, hi, W, marker)
    paths, reach, broke = dp(header, hi, n, layers, W)
    if not paths:
        return 0, None
    # reconstruct greedily: from state (i, pos, uid) pick any allowed
    path = []
    pos, uid = hi, None
    # backward greedy using reach: at layer i, end pos e; need find start p0 = e-W with a uid < next
    seq = []
    e = hi
    for i in range(n, 0, -1):
        found = None
        for p0 in layers.get(i-1, []):
            if p0 + W != e:
                continue
            o, u1, _ = struct.unpack_from('<III', raw, p0)
            if p0 < header:
                continue
            # check predecessor reachability
            if i-1 == 0:
                if p0 != header:
                    continue
            else:
                ok = any(lu < u1 for lu in reach[i-1].get(p0, {}))
                if not ok:
                    continue
            found = (p0, u1)
            break
        if not found:
            return paths, None
        seq.append(found[0])
        e = found[0]
        if i-1 == 0:
            break
    seq.reverse()
    bounds = [header] + [p + W for p in seq]
    return paths, bounds

if __name__ == '__main__':
    for arch, tid, n in [('client',8,126),('client',27,334),('client',18,1567)]:
        raw = load(arch, tid)
        p, b = solve(raw, n)
        print(arch, tid, 'paths', p, 'bounds', b[:4] if b else None, '...', b[-2:] if b else None)

