import sys; sys.path.insert(0,'scratch/t74')
from _probe import load
import struct, collections

def scan_cands(raw, lo, hi, W=13, marker=True, align=None, require_u32pair=True):
    """Return dict ordinal -> sorted list of (start, uid) sorted by start."""
    out = collections.defaultdict(list)
    for p in range(lo, hi - W + 1):
        if align is not None and (p % 4) != align:
            continue
        o, u1, u2 = struct.unpack_from('<III', raw, p)
        if require_u32pair and (u1 != u2 or u1 == 0):
            continue
        if marker and raw[p+W-1] != 0:
            continue
        out[o].append((p, u1))
    for k in out:
        out[k].sort()
    return out

CACHE = {}
def _cand(raw, tag, lo, hi, W, marker, align, pair):
    key = (tag, lo, hi, W, marker, align, pair)
    if key not in CACHE:
        CACHE[key] = scan_cands(raw, lo, hi, W, marker, align, pair)
    return CACHE[key]

def dp_count(raw, tag, lo, hi, n, W=13, marker=True, align=None, pair=True, strict_uid=True):
    layers = _cand(raw, tag, lo, hi, W, marker, align, pair)
    reach = [dict() for _ in range(n + 1)]
    reach[0][lo] = {0: 1}
    for i in range(n):
        nxt = {}
        lay = layers.get(i, [])
        for pos, uids in reach[i].items():
            for p0, uid in lay:
                if p0 < pos:
                    continue
                e = p0 + W
                if e > hi:
                    break
                for u, c in uids.items():
                    if strict_uid and uid <= u:
                        continue
                    d = nxt.setdefault(e, {})
                    d[uid] = d.get(uid, 0) + c
        reach[i + 1] = nxt
        if not nxt:
            return 0, layers, reach, i
    return sum(reach[n].get(hi, {}).values()), layers, reach, n

def dp_walk(raw, tag, lo, hi, n, W=13, marker=True, align=None, pair=True, strict_uid=True):
    paths, layers, reach, broke = dp_count(raw, tag, lo, hi, n, W, marker, align, pair, strict_uid)
    if not paths:
        return paths, None, layers, reach
    pos, lastuid = lo, 0
    bounds = []
    for i in range(n):
        chosen = None
        for p0, uid in layers.get(i, []):
            if p0 < pos:
                continue
            e = p0 + W
            if e > hi:
                break
            if strict_uid and uid <= lastuid:
                continue
            # forward-feasible?
            if i + 1 <= n:
                d = reach[i+1].get(e)
                if not d or uid not in d:
                    continue
            chosen = (p0, uid, e)
            break
        if not chosen:
            return paths, None, layers, reach
        bounds.append((chosen[0], chosen[2], chosen[1]))
        pos, lastuid = chosen[2], chosen[1]
    if pos != hi:
        return paths, None, layers, reach
    return paths, bounds, layers, reach

