                e = p0 + W
                if e > hi: break
                for u, c in uids.items():
                    if strict_uid and uid <= u: continue
                    d = nxt.setdefault(e, {})
                    d[uid] = min(cap, d.get(uid, 0) + c)
        reach[i+1] = nxt
        if not nxt: return 0, f'break@{i}'
    return sum(reach[n].get(hi, {}).values()), 'ok'

