def _dp(b, tag, lo, hi, n, W=13, strict_uid=True, pair=True):
    """identity triple DP: ordinal 分层、非重叠、严格递增 UID。返回 (paths, bounds, layers)。"""
    import struct as _s
    cand = collections.defaultdict(list)
    for p in range(lo, hi - W + 1):
        o, u1, u2 = _s.unpack_from("<III", b, p)
        if pair and u1 != u2:
            continue
        if o >= n:
            continue
        cand[o].append((p, u1))
    for k in cand:
        cand[k].sort()
    states = {(lo, 0): (1, None)}
    hist = [dict(states)]
    for i in range(n):
        nxt = {}
        for (q, pu), (c, _) in states.items():
            for p in cand.get(i, ()):
                if p < q:
                    continue
                if p + W > hi:
                    break
                u = _s.unpack_from("<I", b, p + 4)[0]
                if strict_uid and u <= pu:
                    continue
                key = (p + W, u)
                nxt[key] = (nxt.get(key, (0, None))[0] + c, (q, pu))
        if not nxt:
            return 0, None, len(hist)
        states = nxt
        hist.append(dict(states))
    fin = [k for k in states if k[0] == hi]
    total = sum(states[k][0] for k in fin)
    if len(fin) != 1:
        return total, None, len(hist)
    cur = fin[0]
    bounds = [None] * n
    for i in range(n, 0, -1):
        q, pu = hist[i][cur][1]
        bounds[i - 1] = (q, cur[0])
        cur = (q, pu)
    return total, bounds, len(hist)


def seq_team24(b, n=84507):
    """t24: 变长 + 13B identity(末字节 selector 非 0);UID 对相等 + 严格递增。"""
    H, F = 14, len(b) - 8
    paths, bounds, _ = _dp(b, "24", H, F, n, 13, strict_uid=True, pair=True)
    if paths != 1 or not bounds:
        return None
    lens = [x[1] - x[0] for x in bounds]
    if H + sum(lens) + 8 != len(b):
