def _dp(b, tag, lo, hi, n, W=13, strict_uid=True, pair=True):
    """identity triple DP: ordinal 分层、非重叠、严格递增 UID。返回 (paths, bounds, layers)。"""
    import struct as _s
    cand = _scan(b, lo, hi, n, W, pair)
    states = {(lo, 0): (1, None)}
    hist = [dict(states)]
    for i in range(n):
        nxt = {}
        cs = cand.get(i, ())
        for (q, pu), (c, _) in states.items():
            for p, _u1 in cs:
                if p < q:
                    continue
                if p + W > hi:
                    break
                u = _u1
                if strict_uid and u <= pu:
                    continue
                key = (p + W, u)
                nxt[key] = (nxt.get(key, (0, None))[0] + c, (q, pu))
        if not nxt:
            return 0, None, len(hist)
        states = nxt
        hist.append(dict(states))
    fin = [k for k in states if k[0] == hi]
    total = sum(states[k][0] for k in fin)
    if len(fin) != 1:
        return total, None, len(hist)
    cur = fin[0]
    bounds = [None] * n
    for i in range(n, 0, -1):
        q, pu = hist[i][cur][1]
        bounds[i - 1] = (q, cur[0])
        cur = (q, pu)
    return total, bounds, len(hist)


def _scan(b, lo, hi, n, W, pair):
    """向量化扫描: 每 4 字节对齐 -> 任意对齐,筛 ordinal<n 且(可选)UID 对相等。"""
    import numpy as np
    import collections as _c
    out = _c.defaultdict(list)
    a = np.frombuffer(b, dtype=np.uint8)
    m = len(b)
    for off in range(4):
        cnt = (m - off - 3) // 4
        if cnt <= 2:
            continue
        w = np.frombuffer(b, dtype="<u4", count=cnt, offset=off)
        o = w[:cnt - 2]
        u1 = w[1:cnt - 1]
        u2 = w[2:cnt]
        mask = o < n
        if pair:
            mask = mask & (u1 == u2)
        mask = mask & (u1 > 0)
        idx = np.nonzero(mask)[0]
        if not len(idx):
            continue
        pos = idx * 4 + off
        keep = (pos >= lo) & (pos + W <= hi)
        for p, oo, uu in zip(pos[keep].tolist(), o[idx][keep].tolist(), u1[idx][keep].tolist()):
            out[oo].append((p, uu))
    for k in out:
        out[k].sort()
    return out

