import struct, collections
from t74_frames_part2 import _scan, _dp

# fm24_dump.FIELDS 里本期 9 表涉及的槽位(值 = 行内字节偏移,负数=相对行尾)
ANCHORS = {
    ("client", 21): {"Scti": 3, "Slat": 17, "Slon": 21, "rdui": 25, "duni": 29},
    ("client", 0): {"rdui": 64, "duni": 68},
    ("client", 8): {"rdui_suffix": 17},
    ("client", 7): {"rdui": 3, "duni": 7},
    ("client", 47): {"rdui": -13, "duni": -9},
    ("client", 56): {"rdui": 0, "duni": 4},
}


def sens_grid(b, n, lo, hi, Ws=(12, 13, 14), foots=(7, 8, 9, 10, 12), pair=True):
    """返回 {(W, footer): 路径数}。W 只在 [lo, hi] 内按 footer 重算边界。"""
    out = {}
    for W in Ws:
        for fo in foots:
            h2 = len(b) - fo
            if h2 <= lo:
                out[(W, fo)] = -1
                continue
            var = dict(W=W)
            orig = _SCAN_CACHE.pop((lo, h2, n, W, pair), None)
            paths, bounds, _ = _dp(b, "sens", lo, h2, n, W, strict_uid=True, pair=pair)
            out[(W, fo)] = paths if bounds or paths else paths
            if orig is not None:
                _SCAN_CACHE[(lo, h2, n, W, pair)] = orig
    return out


_SCAN_CACHE = {}


def anchor_report(b, rows, table_arch):
    """按行首/行尾偏移取 u32,报告 rdui==i 与 duni==i 的命中数。"""
    spec = ANCHORS.get(table_arch)
    if not spec or not rows:
        return None
    rep = {}
    for name, off in spec.items():
        if name not in ("rdui", "duni", "rdui_suffix"):
            continue
        hit = 0
        tot = 0
        for i, (s, e) in enumerate(rows):
            p = e + off if off < 0 else s + off
            if p < 0 or p + 4 > len(b):
                continue
            tot += 1
            if struct.unpack_from("<I", b, p)[0] == i:
                hit += 1
        rep[name] = {"offset": off, "hit": hit, "total": tot, "ok": hit == tot and tot > 0}
    return rep


def geo_report(b, rows, table_arch):
    """stadium 的 Scti/Slat/Slon:只报告字节位置与值域,不断言语义。"""
    if table_arch != ("client", 21):
        return None
    out = {}
    for name, off in (("Scti", 3), ("Slat", 17), ("Slon", 21)):
        vals = [struct.unpack_from("<I", b, s + off)[0] for s, e in rows[:2000]]
        out[name] = {"offset": off, "min": min(vals), "max": max(vals),
                     "distinct": len(set(vals))}
    return out

