def rows_fixed(b, H, F, n, st):
    if H + n * st + F != len(b):
        return None
    return [(H + i * st, H + (i + 1) * st) for i in range(n)]


def rows_seq_lang(b, H, F, n):
    p, i, rows, suf = H, 0, [], []
    while p < F:
        r = lstr(b, p, F)
        if not r:
            return None, None
        q, nl, _ = r
        if q + 30 > F:
            return None, None
        rows.append((p, q + 30))
        suf.append((i, q))
        p = q + 30
        i += 1
    return (rows, suf) if i == n and p == F else (None, None)


def rows_seq_weat(b, H, F, n):
    p, i, rows = H, 0, []
    while p < F:
        L = u32(b, p)
        if not (0 < L < 200):
            return None
        e = p + 4 + L + 95 + 13
        if e > F:
            return None
        rows.append((p, e))
        p = e
        i += 1
    return rows if i == n and p == F else None


def rows_seq_derby(b, H, F, n, const):
    p, i, rows = H, 0, []
    while p < F:
        q, tot, k = p, 0, 0
        while k < 8:
            r = lstr(b, q, F)
            if not r:
                break
            q, nl, _ = r
            tot, k = tot + nl, k + 1
        if (q - p) != tot + 4 * k:
            return None
        e = p + tot + const
        if e > F:
            return None
        rows.append((p, e))
        p = e
        i += 1
    return rows if i == n and p == F else None


def rows_id_dp(b, H, F, n, W, foot):
    pos = solo_path(b, H, len(b) - foot, n, W)
    if not pos:
        return None
    starts = [H] + [p + W for p in pos[:-1]]
    ends = [p + W for p in pos]
    return list(zip(starts, ends)) if sum(e - s for s, e in zip(starts, ends)) == len(b) - foot - H else None
